-- Fiche Le présent des verbes en -er (CE1) - conjugaison, notion 'present'. Relancer ce script remplace le contenu de la fiche.
insert into contenu_cours (classe, matiere, titre, contenu, statut, notion_id)
select 'ce1', 'conjugaison', 'Le présent des verbes en -er', $fiche$
[titre]Conjuguer un verbe[/titre]
Le verbe change selon [b]qui[/b] fait l'action. Il a deux parties :
[table=3][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]pronom[/b][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]radical[/b][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]terminaison[/b][/color][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=26]nous[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=26]dans[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=26][b][color=#C62828]ons[/color][/b][/font_size][/center][/cell][/table]
[cadre]Le [b]radical[/b] ne bouge pas (dans-), la [b]terminaison[/b] change (-e, -es, -ons…).
L'[b]infinitif[/b], c'est le verbe « tout nu » : danser, chanter, parler.[/cadre]
[page]
[titre]Les verbes en -er au présent[/titre]
[table=3][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]danser[/b][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]parler[/b][/color][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=21][b]je[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=21]dans[b][color=#C62828]e[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=21]parl[b][color=#C62828]e[/color][/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=21][b]tu[/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=21]dans[b][color=#C62828]es[/color][/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=21]parl[b][color=#C62828]es[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=21][b]il, elle[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=21]dans[b][color=#C62828]e[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=21]parl[b][color=#C62828]e[/color][/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=21][b]nous[/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=21]dans[b][color=#C62828]ons[/color][/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=21]parl[b][color=#C62828]ons[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=21][b]vous[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=21]dans[b][color=#C62828]ez[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=21]parl[b][color=#C62828]ez[/color][/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=21][b]ils, elles[/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=21]dans[b][color=#C62828]ent[/color][/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=21]parl[b][color=#C62828]ent[/color][/b][/font_size][/center][/cell][/table]
[cadre]Les terminaisons : [b]e, es, e, ons, ez, ent[/b].[/cadre]
[page]
[titre]Les lettres qu'on n'entend pas[/titre]
[cadre]je danse, tu danses, il danse, ils dansent : [b]ça se dit pareil[/b] !
Mais ça ne s'écrit pas pareil :
• avec [b]tu[/b], toujours un [b]s[/b] : tu danse[b]s[/b]
• avec [b]ils / elles[/b], toujours [b]ent[/b] : ils danse[b]nt[/b][/cadre]
[cadre=astuce]Le [b]-ent[/b] de « ils dansent » ne se prononce jamais.[/cadre]
[page]
[titre]Être et avoir[/titre]
Ces deux verbes sont spéciaux : il faut les apprendre par cœur.
[table=3][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]être[/b][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]avoir[/b][/color][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20][b]je (j')[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]suis[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]j'ai[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20][b]tu[/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20]es[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20]as[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20][b]il, elle[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]est[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]a[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20][b]nous[/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20]sommes[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20]avons[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20][b]vous[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]êtes[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]avez[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20][b]ils, elles[/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20]sont[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20]ont[/font_size][/center][/cell][/table]
[page]
[titre]Je ou j' ?[/titre]
Devant une voyelle ou un h muet, [b]je[/b] devient [b]j'[/b].
[cadre]j'habite · j'essuie · j'écoute · j'ai
mais : je danse · je cache · je tombe[/cadre]
[page]
[titre]-ger et -cer avec nous[/titre]
[table=2][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]-ger : on garde le e[/b][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]-cer : c devient ç[/b][/color][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]nous plong[b][color=#C62828]e[/color][/b]ons[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]nous ran[b][color=#C62828]ge[/color][/b]ons, nous parta[b][color=#C62828]ge[/color][/b]ons[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]nous lan[b][color=#C62828]ç[/color][/b]ons[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]nous avan[b][color=#C62828]ç[/color][/b]ons[/font_size][/center][/cell][/table]
[cadre=astuce]Sans ce e ou ce ç, on lirait « plongons » (g dur) ou « lancons » (k).[/cadre]
[page]
[titre]-yer : y devient i[/titre]
Les verbes en [b]-oyer[/b] et [b]-uyer[/b] changent le y en [b]i[/b] devant un e muet.
[table=2][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=21]j'essu[b][color=#C62828]ie[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=21]nous essu[b][color=#C62828]y[/color][/b]ons[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=21]je netto[b][color=#C62828]ie[/color][/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=21]vous netto[b][color=#C62828]y[/color][/b]ez[/font_size][/center][/cell][/table]
[cadre=astuce]Avec balayer, on peut écrire [b]il balaye[/b] ou [b]il balaie[/b] : les deux sont justes.[/cadre]
[page]
[titre]Les verbes en -ier[/titre]
[cadre]colorier, trier, skier, planifier : je garde le [b]i[/b] du radical, puis la terminaison.
je colori[b]e[/b] · tu tri[b]es[/b] · nous ski[b]ons[/b] · ils planifi[b]ent[/b][/cadre]
[cadre=astuce]On entend à peine la terminaison, mais elle est bien là : je trie, nous trions.[/cadre]
[page]
[titre]Je retiens[/titre]
[cadre]• Verbes en -er : [b]e, es, e, ons, ez, ent[/b].
• tu → s ; ils, elles → ent (muet).
• être : suis, es, est, sommes, êtes, sont. avoir : ai, as, a, avons, avez, ont.
• nous plongeons, nous lançons. j'essuie, je nettoie.[/cadre]
$fiche$, 'publie', n.id from contenu_notions n where n.code = 'present'
on conflict (notion_id, classe) where statut <> 'archive'
do update set titre = excluded.titre, contenu = excluded.contenu, matiere = excluded.matiere, statut = 'publie', modifie_le = now()
returning id, classe, titre, statut;
